export class MinHeap {
    private values: number[] = [];

    get size(): number {
        return this.values.length;
    }

    insert(value: number): void {
        this.values.push(value);
        this.bubbleUp(this.values.length - 1);
    }

    extractMin(): number | undefined {
        if (this.values.length === 0) {
            return undefined;
        }
        const min = this.values[0];
        const last = this.values.pop() as number;
        if (this.values.length > 0) {
            this.values[0] = last;
            this.bubbleDown(0);
        }
        return min;
    }

    private bubbleUp(index: number): void {
        while (index > 0) {
            const parent = Math.floor((index - 1) / 2);
            if (this.values[parent] <= this.values[index]) {
                return;
            }
            this.swap(parent, index);
            index = parent;
        }
    }

    private bubbleDown(index: number): void {
        while (true) {
            const left = index * 2 + 1;
            const right = left + 1;
            let smallest = index;
            if (left < this.values.length && this.values[left] < this.values[smallest]) {
                smallest = left;
            }
            if (right < this.values.length && this.values[right] < this.values[smallest]) {
                smallest = right;
            }
            if (smallest === index) {
                return;
            }
            this.swap(index, smallest);
            index = smallest;
        }
    }

    private swap(a: number, b: number): void {
        const temp = this.values[a];
        this.values[a] = this.values[b];
        this.values[b] = temp;
    }
}
